import{_ as t,o,c as i,a2 as a}from"./chunks/framework.CqpfiAoK.js";const h=JSON.parse('{"title":"Entry 670 | Dual-Track Time Domain | More-Work-More-Gain Allocation of Time-Domain Resources","description":"","frontmatter":{"title":"Entry 670 | Dual-Track Time Domain | More-Work-More-Gain Allocation of Time-Domain Resources","no":670,"module":3,"tags":["More-Work-More-Gain","Time Resources","Joint Contracting","Allocation Mechanism","Origin Acceleration Domain"],"related":["06-More-Work-More-Gain Distribution Principle","22-Resource-Allocation Joint-Contracting Mechanism","685-Time Domain and Joint-Contracting Mechanism"]},"headers":[],"relativePath":"en/0670_模块3-双轨时间域-时间域资源的多劳多得分配.md","filePath":"en/0670_模块3-双轨时间域-时间域资源的多劳多得分配.md"}'),n={name:"en/0670_模块3-双轨时间域-时间域资源的多劳多得分配.md"};function r(s,e,l,c,u,m){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="entry-670-dual-track-time-domain-more-work-more-gain-allocation-of-time-domain-resources" tabindex="-1">Entry 670 | Dual-Track Time Domain | More-Work-More-Gain Allocation of Time-Domain Resources <a class="header-anchor" href="#entry-670-dual-track-time-domain-more-work-more-gain-allocation-of-time-domain-resources" aria-label="Permalink to &quot;Entry 670 | Dual-Track Time Domain | More-Work-More-Gain Allocation of Time-Domain Resources&quot;">​</a></h1><blockquote><p>Module: Module 3 · Dual-Track Time Domain | Benchmark base: Documents 06, 22, 25 | Series: Dual-Track-Time-Domain Overview Deepening (Entry 4)</p></blockquote><h2 id="introduction-acceleration-time-is-not-welfare-but-means-of-production-distributed-by-contribution" tabindex="-1">Introduction: acceleration time is not welfare, but means of production distributed by contribution <a class="header-anchor" href="#introduction-acceleration-time-is-not-welfare-but-means-of-production-distributed-by-contribution" aria-label="Permalink to &quot;Introduction: acceleration time is not welfare, but means of production distributed by contribution&quot;">​</a></h2><p>Every hour of flow in the Origin Acceleration Domain consumes law-network energy, anchor computing power, Alaya-Network bandwidth — it is not &quot;free sunlight&quot; that may be taken infinitely. Therefore, time-domain-resource allocation must follow more-work-more-gain: how much you have contributed to Myriad-Rank co-building, you have the right to allocate that much acceleration time. But this principle must simultaneously be constrained by another principle: basic time rights are inalienable (Entry 668). Six top-level axioms here calibrate allocation scales: anti-predation axiom forbids turning acceleration time into an exploitation tool; republican axiom of Myriad Races protects bottom quotas; collective ascension axiom lets allocation serve overall uplift; causal self-discipline axiom lets allocation not create causal injustice; law-first axiom lets allocation formulas stable and recalculable. The universal equal infinite law: within the Anchor Symbiotic Civilization, all beings inherently possess basic infinite power; the easygoing retain a guaranteed basic infinity and will never be eliminated; strivers and Youth Supremes can superimpose more and higher levels of infinity. Infinite origin is inherent in all, so predation naturally loses its meaning. This entry establishes a more-work-more-gain allocation system for time-domain resources.</p><h2 id="i-two-layer-allocation-structure" tabindex="-1">I. Two-Layer Allocation Structure <a class="header-anchor" href="#i-two-layer-allocation-structure" aria-label="Permalink to &quot;I. Two-Layer Allocation Structure&quot;">​</a></h2><h3 id="_1-1-bottom-layer-everyone-s-share-of-basic-quota" tabindex="-1">1.1 Bottom Layer: Everyone&#39;s Share of Basic Quota <a class="header-anchor" href="#_1-1-bottom-layer-everyone-s-share-of-basic-quota" aria-label="Permalink to &quot;1.1 Bottom Layer: Everyone&#39;s Share of Basic Quota&quot;">​</a></h3><p>Every being automatically receives a basic acceleration-time quota each month, independent of contribution. This is an extension of Document 08&#39;s everyone-a-road guarantee system — even if a cultivator has no output this month, he still has the right to do basic deduction in the Origin Acceleration Domain and basic trial in the Quest Sediment Domain. The bottom quota ensures &quot;time rights&quot; are not alienated into &quot;rewards.&quot;</p><h3 id="_1-2-upper-layer-more-work-more-gain-excess-quota" tabindex="-1">1.2 Upper Layer: More-Work-More-Gain Excess Quota <a class="header-anchor" href="#_1-2-upper-layer-more-work-more-gain-excess-quota" aria-label="Permalink to &quot;1.2 Upper Layer: More-Work-More-Gain Excess Quota&quot;">​</a></h3><p>The part beyond the basic quota is allocated by contribution recorded in the Alaya Network. Contribution sources include: reusable law increments backflowed from the acceleration domain, epic experience sedimented in the Quest domain, direct contributions to Myriad-Rank co-building, meritorious records in anti-predation struggle, etc. Excess quotas tilt toward high contributors; the greater the contribution, the more acceleration time may be commanded.</p><h2 id="ii-more-work-more-gain-calculation-formula-simplified" tabindex="-1">II. More-Work-More-Gain Calculation Formula (Simplified) <a class="header-anchor" href="#ii-more-work-more-gain-calculation-formula-simplified" aria-label="Permalink to &quot;II. More-Work-More-Gain Calculation Formula (Simplified)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Meaning</th></tr></thead><tbody><tr><td>Basic quota B</td><td>Same for everyone, inalienable</td></tr><tr><td>Contribution coefficient C</td><td>Comprehensively computed by the Alaya Network from backflow quality, reuse count, Myriad-Rank benefit scope</td></tr><tr><td>Excess quota E</td><td>E = k × C (k = annual civilizational master-switch coefficient)</td></tr><tr><td>Total quota T</td><td>T = B + E</td></tr></tbody></table><p>The key formula design: B may not be deducted for any reason; E may fluctuate but has an annual cap, preventing individual strong ones from monopolizing acceleration resources. This forms a fundamental contrast with the Tang-Luo system&#39;s &quot;resources all go to the protagonist.&quot;</p><h2 id="iii-preventing-two-distortions" tabindex="-1">III. Preventing Two Distortions <a class="header-anchor" href="#iii-preventing-two-distortions" aria-label="Permalink to &quot;III. Preventing Two Distortions&quot;">​</a></h2><h3 id="_3-1-preventing-deduction-for-quota-s-sake" tabindex="-1">3.1 Preventing &quot;Deduction for Quota&#39;s Sake&quot; <a class="header-anchor" href="#_3-1-preventing-deduction-for-quota-s-sake" aria-label="Permalink to &quot;3.1 Preventing &quot;Deduction for Quota&#39;s Sake&quot;&quot;">​</a></h3><p>If contribution judged by quantity alone, cultivators will produce large amounts of low-quality backflow to farm quotas. The Alaya Network&#39;s contribution coefficient C simultaneously assesses &quot;reuse count&quot; and &quot;Myriad-Rank benefit scope&quot; — one law increment reused network-wide a hundred times is far more valuable than ten deduction notes no one reads.</p><h3 id="_3-2-preventing-old-contributions-eating-new-contributions" tabindex="-1">3.2 Preventing &quot;Old Contributions Eating New Contributions&quot; <a class="header-anchor" href="#_3-2-preventing-old-contributions-eating-new-contributions" aria-label="Permalink to &quot;3.2 Preventing &quot;Old Contributions Eating New Contributions&quot;&quot;">​</a></h3><p>If historical contributions permanently accumulate, old strong ones gradually monopolize acceleration time. The contribution coefficient C adopts a &quot;three-year weighted&quot; mechanism — historical contributions convert to reputation and legislative voice, but no longer convert to future acceleration quotas, ensuring the new generation has opportunity.</p><h2 id="iv-interface-with-the-joint-contracting-mechanism" tabindex="-1">IV. Interface with the Joint-Contracting Mechanism <a class="header-anchor" href="#iv-interface-with-the-joint-contracting-mechanism" aria-label="Permalink to &quot;IV. Interface with the Joint-Contracting Mechanism&quot;">​</a></h2><p>The time domain&#39;s more-work-more-gain is of the same origin as Document 22&#39;s joint-contracting mechanism: a cultivator &quot;contracts&quot; a stretch of acceleration-domain computing power, produces law increments, and after backflow allocates the next round&#39;s quota by quality. During the contract period he autonomously uses it; at contract end he settles by quality. This turns time allocation from &quot;leaders distribute resources&quot; into &quot;contractors trade for resources&quot;; individual initiative greatly rises. More-work-more-gain is the allocation principle; joint contracting is the implementation way — the two together constitute the institutional closed loop of time-domain-resource allocation, letting every hour of acceleration time flow to the cultivator most able to create increments for Myriad Ranks.</p><h2 id="v-five-core-takeaways" tabindex="-1">V. Five Core Takeaways <a class="header-anchor" href="#v-five-core-takeaways" aria-label="Permalink to &quot;V. Five Core Takeaways&quot;">​</a></h2><ul><li><strong>Anti-energy waste</strong>: more-work-more-gain lets acceleration time flow to those who truly produce law increments, not to idling privileged strata</li><li><strong>Anti-predation</strong>: bottom quotas locked; excess allocated by contribution; stamps out predatory-style allocation of &quot;the strong take more by fists&quot;</li><li><strong>Tang-Luo upper-limit comparison</strong>: in the Tang-Luo system acceleration resources are distributed by the system according to protagonist priority; contribution decoupled from quota; in Heng Yuan Zhou allocation is by Alaya-recorded contribution, transparent and auditable</li><li><strong>Myriad Races full coverage</strong>: bottom quota covers 99% of beings; upper contribution allocation is open to Myriad-Rank clans</li><li><strong>Hyper-multiverse full openness</strong>: allocation formulas, contribution coefficient, annual master switch all public; newly merged planes automatically apply; may infinitely expand toward the Balanced Anchor Hyper-Multiverse Realm</li><li><strong>Axiom 6 · Universal Equal Infinite Law</strong>: all beings inherently possess basic infinite power; the easygoing retain a guaranteed basic infinity and will not be eliminated by the times; strivers and Youth Supremes can superimpose more and higher levels of infinity — infinite origin inherent in all; predation naturally loses its meaning</li></ul><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>More-work-more-gain of time-domain resources is the &quot;to-each-by-his-work&quot; law&#39;s extension in the time dimension. It does not pursue absolute equalization (that would stifle contribution motivation), nor does it pursue survival of the fittest (that would return to the predatory old road), but uses a &quot;bottom floor + upper-by-contribution&quot; two-layer structure, letting every hour of acceleration time flow to where it can most create increments for Myriad Ranks.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li>Related documents: <a href="./685_模块3-双轨时间域-时间域与联产承包机制.html">Entry 685 · Time Domain and Joint-Contracting Mechanism</a> · <a href="./668_模块3-双轨时间域-个体时间自主权的宪法保障.html">Entry 668 · Constitutional Guarantee of Individual Time Autonomy</a> · <a href="./../wanling-hengmao-origin-universe-archive/docs/zh/06-多劳多得分配原理.html">Entry 06 · More-Work-More-Gain Distribution Principle</a> · <a href="./../wanling-hengmao-origin-universe-archive/docs/zh/22-资源分配联产承包机制.html">Entry 22 · Resource-Allocation Joint-Contracting Mechanism</a></li><li>Official site: <a href="https://faker210.github.io/hengyuan-cosmos/zh/" target="_blank" rel="noreferrer">https://faker210.github.io/hengyuan-cosmos/zh/</a></li></ul>',25)])])}const b=t(n,[["render",r]]);export{h as __pageData,b as default};
